package com.hotel.hotel_backend.config;
import com.hotel.hotel_backend.model.Hotel;import com.hotel.hotel_backend.repository.HotelRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;
@Configuration public class DataSeeder {
 @Bean CommandLineRunner seedHotels(HotelRepository repo){return args->{if(repo.count()==0){String[][] data={{"The Grand Palace","Faridabad","Faridabad Sec 30, Haryana","4.6","5999","https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=900"},{"Hotel Royal Inn","Delhi","Karol Bagh, Delhi","4.3","2299","https://images.unsplash.com/photo-1566073771259-6a8506099945?w=900"},{"The Olive Suites","Delhi","Saket, Delhi","4.4","2999","https://images.unsplash.com/photo-1590490360182-c33d57733427?w=900"},{"ITC Narmada Luxury","Delhi","Aerocity, Delhi","4.8","6999","https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=900"}};for(String[] d:data){Hotel h=new Hotel();h.setName(d[0]);h.setCity(d[1]);h.setLocation(d[2]);h.setRating(Double.parseDouble(d[3]));h.setStartingPrice(Double.parseDouble(d[4]));h.setFacilities("WiFi, AC, Restaurant");h.setImageUrl(d[5]);h.setStatus("APPROVED");repo.save(h);}}};}
}
